def min_Swaps(s1: str, s2: str) -> int:
    if len(s1) != len(s2):
        return -1
    a = b = 0
    for x, y in zip(s1, s2):
        if x == '1' and y == '0':
            a += 1
        elif x == '0' and y == '1':
            b += 1
    if s1.count('1') != s2.count('1'):
        return -1
    return a  # equals min(a, b) + a pairing; a == b when counts match

assert min_Swaps("1101", "1110") == 1
